#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_posX;
uniform float amzp_posY;
uniform float amzp_intensity;
uniform float amzp_flareHue;
uniform float amzp_flareType;
uniform float amzp_glowSize;
uniform float amzp_ghostStr;
uniform float amzp_streakStr;
uniform float amzp_starburstStr;



        float3 hueShift(float3 col, float shift) {
            float3 P = float3(0.55735) * dot(float3(0.55735), col);
            float3 U = col - P;
            float3 V = cross(float3(0.55735), U);
            col = U * cos(shift * 6.2832) + V * sin(shift * 6.2832) + P;
            return max(float3(0.0), col);
        }


        float hash(float n) { return fract(sin(n) * 43758.5453123); }


        float3 lensFlare(float2 uv, float2 amzLocal_pos) {
            float2 main = uv - amzLocal_pos;
            float dist = length(main);
            float ang = atan(main.y, main.x);

            float3 f = float3(0.0);


            float3 colCore = hueShift(float3(1.0, 0.9, 0.8), amzp_flareHue);
            float3 colStreak = hueShift(float3(0.8, 0.5, 0.2), amzp_flareHue);
            float3 colGhost = hueShift(float3(0.9, 0.8, 1.0), amzp_flareHue);


            int type = int(floor(amzp_flareType + 0.5));

            float activeStreak = 0.0;
            float activeStar = 0.0;
            float activeGhosts = 0.0;

            if (type == 0) {

                activeStreak = 0.0;
                activeStar = 0.0;
                activeGhosts = 0.0;
            } else if (type == 1) {

                activeStreak = 1.0;
                activeStar = 0.0;
                activeGhosts = 0.2;
            } else if (type == 2) {

                activeStreak = 0.0;
                activeStar = 1.0;
                activeGhosts = 0.1;
            } else {

                activeStreak = 0.3;
                activeStar = 0.2;
                activeGhosts = 1.0;
            }


            float sStr = amzp_streakStr * activeStreak;
            float stStr = amzp_starburstStr * activeStar;
            float gStr = amzp_ghostStr * activeGhosts;


            float core = 1.0 / (dist * (20.0 / amzp_glowSize) + 0.5);
            core = pow(core, 2.0);
            f += colCore * core * 2.0;


            if (stStr > 0.01) {
                float rays = abs(cos(ang * 3.0)) * 0.5 + abs(cos(ang * 12.0)) * 0.2;
                rays += smoothstep(0.0, 1.0, abs(sin(ang * 100.0))) * 0.1;
                rays *= 0.2 / (dist + 0.1);
                f += colCore * rays * stStr;
            }


            if (sStr > 0.01) {
                float vDist = abs(main.y);
                float streak = exp(-vDist * 40.0);
                streak *= smoothstep(1.5, 0.1, abs(main.x));
                f += colStreak * streak * sStr;
            }


            if (gStr > 0.01) {
                float2 ghostVec = -amzLocal_pos * 0.5;
                for (float i = 0.0; i < 5.0; i++) {
                    float t = fract(i * 0.35 + 0.3);
                    float2 gPos = amzLocal_pos + ghostVec * (t * 4.0);
                    float amzLocal_size = 0.05 + 0.15 * hash(i * 12.3);
                    float chr = 0.02 * dist;

                    float3 ghostCol = float3(0.0);
                    float d = length(uv - gPos);

                    ghostCol.r = smoothstep(amzLocal_size + chr, amzLocal_size - 0.01 + chr, d);
                    ghostCol.g = smoothstep(amzLocal_size,       amzLocal_size - 0.01,       d);
                    ghostCol.b = smoothstep(amzLocal_size - chr, amzLocal_size - 0.01 - chr, d);

                    float hollow = smoothstep(0.0, amzLocal_size * 0.8, d);
                    ghostCol *= 0.5 + 0.5 * hollow;

                    float alpha = 0.1 * gStr * (1.0 - t * 0.5);
                    f += ghostCol * alpha * colGhost;
                }
            }

            return f * amzp_intensity;
        }

        void amzRender() {
            float2 uv = amzScreenNorm();
            float2 aspectVec = float2(layer.x / layer.y, 1.0);


            float2 cUV = (uv - 0.5) * aspectVec;


            float2 lightPos = (float2(amzp_posX, 1.0 - amzp_posY) - 0.5) * aspectVec;


            float3 col = amzTexture(0, uv).rgb;


            float3 flare = lensFlare(cUV, lightPos);
            col += flare;


            col = col * 0.8;
            const float a = 2.51;
            const float b = 0.03;
            const float c = 2.43;
            const float d = 0.59;
            const float e = 0.14;
            col = clamp((col*(a*col+b))/(col*(c*col+d)+e), 0.0, 1.0);


            col = pow(col, float3(1.0/2.2));

            amzOutput = float4(col, 1.0);
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

